import java.util.*;

class Solution {
  public int maxFrequencyScore(int[] nums, long k) {
    Arrays.sort(nums);
    long[] prefix = new long[nums.length + 1];
    for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    int left = 0, answer = 1;
    for (int right = 0; right < nums.length; right++) {
      while (left <= right && cost(nums, prefix, left, right) > k) left++;
      answer = Math.max(answer, right - left + 1);
    }
    return answer;
  }

  private long cost(int[] a, long[] p, int l, int r) {
    int mid = (l + r) >>> 1;
    long median = a[mid];
    long leftCost = median * (mid - l) - (p[mid] - p[l]);
    long rightCost = (p[r + 1] - p[mid + 1]) - median * (r - mid);
    return leftCost + rightCost;
  }
}
